package com.autosphere.controller;
import com.autosphere.model.*;import com.autosphere.repository.*;import com.autosphere.service.PriceCalculator;import org.springframework.web.bind.annotation.*;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import java.util.*;
@RestController @RequestMapping("/api") public class VehicleController {private final VehicleRepository vehicles;private final CityPriceRepository prices;private final PriceCalculator calculator;public VehicleController(VehicleRepository v,CityPriceRepository p,PriceCalculator c){vehicles=v;prices=p;calculator=c;}@GetMapping("/health") public Map<String,String> health(){return Map.of("status","ok","service","autosphere-api");}@GetMapping("/vehicles") public List<Vehicle> all(){return vehicles.findAll();}@GetMapping("/vehicles/{id}") public Vehicle one(@PathVariable Long id){return vehicles.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));}@GetMapping("/pricing/{vehicleId}") public Map<String,Object> price(@PathVariable Long vehicleId,@RequestParam(defaultValue="Lucknow") String city){Vehicle v=vehicles.findById(vehicleId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));CityPrice p=prices.findByVehicleIdAndCityIgnoreCase(vehicleId,city).orElse(new CityPrice(v,city,0,0,0));long total=calculator.onRoadPrice(v.exShowroomPrice,p.roadTax,p.insurance,p.accessories);return Map.of("vehicleId",vehicleId,"city",city,"exShowroom",v.exShowroomPrice,"roadTax",p.roadTax,"insurance",p.insurance,"accessories",p.accessories,"onRoadPrice",total,"validityNote","Indicative demo price; confirm with showroom.");}}
